    while (continuer == 0) {
        if (str[i] >= 'A' && str[i] <= 'Z')
            continuer = 1;
        if (str[i] >= 'a' && str[i] <= 'z') {
            str[i] = str[i] - 32;
            continuer = 1;
        }
        i++;
    }
    return (str);
}

char *my_strcapitalize(char *str)
{
    int i = 0;

    start_capitalize(str);
    for (i = 0; str[i] != '\0'; i++) {
        if (str[i] == ' ' || str[i] == '.' || str[i] == '!' ||
            str[i] == ':' || str[i] == '?' || str[i] == ';')
            is_capitalize_espace(str, i);
